func TestEnumLicenseId(t *testing.T) {
	t.Run("NewFromString_MIT", func(t *testing.T) {
		t.Parallel()
		val, err := NewLicenseIdFromString("MIT")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, LicenseId("MIT"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Apache_2_0", func(t *testing.T) {
		t.Parallel()
		val, err := NewLicenseIdFromString("Apache-2.0")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, LicenseId("Apache-2.0"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewLicenseIdFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewLicenseIdFromString("MIT")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

